{"cmd":"npx --yes --package playwright node <<'JS'
const { chromium } = require('playwright');

(async () => {
  const base = 'http://127.0.0.1:3000';
  const consent = JSON.stringify({ analytics: false, media: false });
  const targets = [
    { path: '/', file: 'docs/backend-handbuch/assets/screenshots/frontend-homepage.png', width: 1440, height: 980, mobile: false },
    { path: '/', file: 'docs/backend-handbuch/assets/screenshots/frontend-homepage-mobile.png', width: 390, height: 844, mobile: true },
    { path: '/events/mirjam-grossmann-management-unternehmensberatung-2026-06-25', file: 'docs/backend-handbuch/assets/screenshots/frontend-eventdetail.png', width: 1440, height: 980, mobile: false }
  ];

  const browser = await chromium.launch({ headless: true });
  try {
    for (const target of targets) {
      const context = await browser.newContext({
        viewport: { width: target.width, height: target.height },
        deviceScaleFactor: 1,
        isMobile: target.mobile,
        hasTouch: target.mobile
      });
      await context.addInitScript((value) => {
        window.localStorage.setItem('stuttgart-live-consent-v1', value);
      }, consent);
      const page = await context.newPage();
      await page.goto(`${base}${target.path}`, { waitUntil: 'domcontentloaded' });
      await page.waitForLoadState('networkidle', { timeout: 15000 }).catch(() => {});
      await page.waitForTimeout(1000);
      const bannerVisible = await page.locator('.consent-banner:not([hidden])').count();
      if (bannerVisible > 0) {
        throw new Error(`Consent banner still visible for ${target.path}`);
      }
      await page.screenshot({ path: target.file, fullPage: false });
      console.log(`wrote ${target.file}`);
      await context.close();
    }
  } finally {
    await browser.close();
  }
})().catch((error) => {
  console.error(error);
  process.exit(1);
});
